<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #17212b; background: #f5f7fa; }
    body { max-width: 760px; margin: 48px auto; padding: 0 20px; }
    h1 { margin: 0 0 24px; }
    form, .project-row, .task-row { display: flex; gap: 12px; align-items: center; }
    form { margin-bottom: 24px; }
    input { flex: 1; min-width: 0; padding: 10px 12px; border: 1px solid #aab5c0; border-radius: 6px; font: inherit; }
    button { padding: 10px 14px; border: 0; border-radius: 6px; background: #175cd3; color: white; font: inherit; cursor: pointer; }
    button:focus-visible, input:focus-visible { outline: 3px solid #84adff; outline-offset: 2px; }
    .project-row { justify-content: space-between; padding: 14px; margin: 10px 0; border: 1px solid #d7dee6; border-radius: 8px; background: white; }
    .task-row { justify-content: space-between; padding: 14px; margin: 10px 0; border: 1px solid #d7dee6; border-radius: 8px; background: white; }
    .task-row label { display: flex; align-items: center; gap: 10px; }
    .task-row input { flex: initial; }
    .error { color: #b42318; min-height: 1.5em; }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);

    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) {
        const projects = await fetch('/api/projects').then((response) => response.json());
        const project = projects.find((item) => String(item.id) === match[1]);
        if (!project) { app.innerHTML = '<h1>Project not found</h1><button id="back">Projects</button>'; }
        else app.innerHTML = `<button id="back">Projects</button><h1>${escapeHtml(project.name)}</h1><form id="task-form"><label for="task-title">Task title</label><input id="task-title" name="title" type="text"><button type="submit">Create task</button></form><p class="error" role="alert" aria-live="polite"></p><label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select><section id="tasks" aria-label="Tasks"></section>`;
        document.querySelector('#back').addEventListener('click', () => { location.href = '/'; });
        if (project) {
          const taskList = document.querySelector('#tasks');
          const filter = document.querySelector('#task-filter');
          async function loadTasks() {
            const tasks = await fetch(`/api/projects/${match[1]}/tasks`).then((response) => response.json());
            const visibleTasks = tasks.filter((task) => filter.value === 'All' || (filter.value === 'Completed') === task.completed);
            taskList.innerHTML = visibleTasks.map((task) => `<article class="task-row" data-testid="task-row"><span>${escapeHtml(task.title)}</span><label><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" data-task-id="${task.id}" ${task.completed ? 'checked' : ''}></label></article>`).join('');
            taskList.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => checkbox.addEventListener('change', async () => {
              await fetch(`/api/tasks/${checkbox.dataset.taskId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
              await loadTasks();
            }));
          }
          filter.addEventListener('change', loadTasks);
          document.querySelector('#task-form').addEventListener('submit', async (event) => {
            event.preventDefault();
            const error = document.querySelector('.error');
            const title = document.querySelector('#task-title').value.trim();
            error.textContent = '';
            if (!title) { error.textContent = 'Task title is required'; return; }
            const response = await fetch(`/api/projects/${match[1]}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
            if (!response.ok) { error.textContent = 'Task title is required'; return; }
            document.querySelector('#task-title').value = '';
            await loadTasks();
          });
          await loadTasks();
        }
        return;
      }
      app.innerHTML = '<h1>Workboard</h1><form id="create-form"><label for="project-name">Project name</label><input id="project-name" name="name" type="text"><button type="submit">Create project</button></form><p class="error" role="alert" aria-live="polite"></p><section id="projects" aria-label="Projects"></section>';
      const list = document.querySelector('#projects');
      async function loadProjects() {
        const projects = await fetch('/api/projects').then((response) => response.json());
        list.innerHTML = projects.map((project) => `<article class="project-row" data-testid="project-row"><span>${escapeHtml(project.name)}</span><button type="button" data-project-id="${project.id}">Open project</button></article>`).join('');
        list.querySelectorAll('button').forEach((button) => button.addEventListener('click', () => { location.href = `/projects/${button.dataset.projectId}`; }));
      }
      await loadProjects();
      document.querySelector('#create-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const error = document.querySelector('.error');
        const name = document.querySelector('#project-name').value.trim();
        error.textContent = '';
        if (!name) { error.textContent = 'Project name is required'; return; }
        const response = await fetch('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
        if (!response.ok) { error.textContent = 'Project name is required'; return; }
        document.querySelector('#project-name').value = '';
        await loadProjects();
      });
    }
    render();
  </script>
</body>
</html>
